def anti_shuffle(s):
    words = s.split(' ')
    sorted_words = [''.join(sorted(word)) for word in words]
    result = []

    for i in range(len(words)):
        if words[i] == '':
            result.append('')
        else:
            result.append(sorted_words[i])

    return ' '.join(result)

